String deptId = "demandeur_enLigne";

public void addToDept(String userID,String deptId){
    EmploymentDao employmentDao =(EmploymentDao) AppUtil.getApplicationContext().getBean("employmentDao");
    UuidGenerator uuid = UuidGenerator.getInstance();
    String pId = uuid.getUuid();
    Employment emp = new Employment();
    emp.setId(pId);
    emp.setUserId(userID);
    emp.setOrganizationId("rsu");
    emp.setDepartmentId(deptId);
    LogUtil.warn("----- User "+userID+" assigned to departement --->"+deptId,String.valueOf(employmentDao.addEmployment(emp)));
    LogUtil.info("--------------- Affect to departement ---------->", String.valueOf(employmentDao.assignUserToDepartment(userID, deptId)));
}

try {
    UserSecurity us = DirectoryUtil.getUserSecurity();
    UserDao userDao = (UserDao) AppUtil.getApplicationContext().getBean("userDao");
    RoleDao roleDao = (RoleDao) AppUtil.getApplicationContext().getBean("roleDao");
    GroupDao groupDao = (GroupDao) AppUtil.getApplicationContext().getBean("groupDao");
    DepartmentDao departmentDao = (DepartmentDao) AppUtil.getApplicationContext().getBean("departmentDao");
    Department department = departmentDao.getDepartment(deptId);
    User user = new User();
    user.setId(email);
    user.setUsername(email);
    user.setTimeZone("0");
    user.setActive(1);
    user.setFirstName(firstName);
    user.setLastName(lastName);
    user.setEmail(email);
    //Check if there is user security implementation, using it to encrypt password
    if (us != null) {
        user.setPassword(us.encryptPassword(email, password));
    } else {
        user.setPassword(StringUtil.md5Base16(password));
    }
    user.setConfirmPassword(password);
    
    Set groupSet = new HashSet();
    String groupName="RSU Users";
    Group group = groupDao.getGroupByName(groupName);
    if (group != null) {
        groupSet.add(group);
    }
    user.setGroups(groupSet);
    
    Set roleSet = new HashSet();
    Role role = roleDao.getRoleByName("User");
    roleSet.add(role);
    user.setRoles(roleSet);
    
   
    

    
    
    userDao.addUser(user);

    if ( department != null ){
        LogUtil.info("departement non nul",department.toString());
        LogUtil.warn("departement=",deptId);
        addToDept(email,deptId);
}
    
    if (us != null) {
        us.insertUserPostProcessing(user);
        
    }
} catch (Exception e) {
LogUtil.error("Sample app -  Create User form", e, "user error!!");
}
